import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Arrays;
import java.util.Random;

/** Verifies the BitMatrix lowest/highest-set-bit refactor two ways: identity vs original loops, and
 *  a differential test of getEnclosingRectangle/getTopLeftOnBit/getBottomRightOnBit old vs new. */
public final class BmDiff {

  // Original inline-loop implementations, reproduced verbatim for the identity check.
  static int origLowest(int theBits) {
    int bit = 0;
    while ((theBits << (31 - bit)) == 0) {
      bit++;
    }
    return bit;
  }

  static int origHighest(int theBits) {
    int bit = 31;
    while ((theBits >>> bit) == 0) {
      bit--;
    }
    return bit;
  }

  static int newLowest(int value) {
    return Integer.numberOfTrailingZeros(value);
  }

  static int newHighest(int value) {
    return 31 - Integer.numberOfLeadingZeros(value);
  }

  static void identityCheck() {
    long checks = 0;
    long mism = 0;
    // all single-bit values
    for (int k = 0; k < 32; k++) {
      int v = 1 << k;
      checks += 2;
      if (origLowest(v) != newLowest(v) || origHighest(v) != newHighest(v)) {
        mism++;
        System.out.println("IDENTITY MISMATCH v=0x" + Integer.toHexString(v));
      }
    }
    // edge values + heavy random sweep (skip v==0, undefined for the loops)
    Random r = new Random(1);
    int[] edges = { 1, -1, 0x80000000, 0x7FFFFFFF, 0xFFFF, 0xFFFF0000, 3, 0xC0000003 };
    for (int v : edges) {
      checks += 2;
      if (origLowest(v) != newLowest(v) || origHighest(v) != newHighest(v)) {
        mism++;
        System.out.println("IDENTITY MISMATCH edge v=0x" + Integer.toHexString(v));
      }
    }
    for (int i = 0; i < 20000000; i++) {
      int v = r.nextInt();
      if (v == 0) {
        continue;
      }
      checks += 2;
      if (origLowest(v) != newLowest(v) || origHighest(v) != newHighest(v)) {
        mism++;
        if (mism <= 10) {
          System.out.println("IDENTITY MISMATCH v=0x" + Integer.toHexString(v) +
              " lo(orig=" + origLowest(v) + ",new=" + newLowest(v) + ")" +
              " hi(orig=" + origHighest(v) + ",new=" + newHighest(v) + ")");
        }
      }
    }
    System.out.println("Identity checks: " + checks + ", mismatches: " + mism);
  }

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static final class Api {
    final java.lang.reflect.Constructor<?> ctor;
    final Method set;
    final Method encl;
    final Method topLeft;
    final Method bottomRight;
    Api(ClassLoader cl) throws Exception {
      Class<?> c = Class.forName("com.google.zxing.common.BitMatrix", true, cl);
      ctor = c.getConstructor(int.class, int.class);
      set = c.getMethod("set", int.class, int.class);
      encl = c.getMethod("getEnclosingRectangle");
      topLeft = c.getMethod("getTopLeftOnBit");
      bottomRight = c.getMethod("getBottomRightOnBit");
    }
    Object make(int w, int h, boolean[][] on) throws Exception {
      Object m = ctor.newInstance(w, h);
      for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
          if (on[y][x]) {
            set.invoke(m, x, y);
          }
        }
      }
      return m;
    }
  }

  static String sig(Object arr) {
    return arr == null ? "null" : Arrays.toString((int[]) arr);
  }

  public static void main(String[] args) throws Exception {
    System.out.println("=== Part 1: helper identity vs original loops ===");
    identityCheck();

    System.out.println("=== Part 2: differential test of public methods ===");
    Api oldA = new Api(loader(args[0]));
    Api newA = new Api(loader(args[1]));
    Random r = new Random(42);
    long total = 0;
    long nonNull = 0;
    long mism = 0;
    // widths include non-multiples of 32 to exercise rowSize/word boundaries
    int[] dims = { 1, 2, 7, 15, 16, 31, 32, 33, 48, 63, 64, 65, 100 };
    for (int trial = 0; trial < 120000; trial++) {
      int w = dims[r.nextInt(dims.length)];
      int h = dims[r.nextInt(dims.length)];
      boolean[][] on = new boolean[h][w];
      int mode = r.nextInt(5);
      for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
          switch (mode) {
            case 0: on[y][x] = r.nextBoolean(); break;
            case 1: on[y][x] = false; break;
            case 2: on[y][x] = r.nextInt(20) == 0; break; // sparse
            case 3: on[y][x] = (x == 0 || x == w - 1 || y == 0 || y == h - 1); break; // border
            default: on[y][x] = (x + y) % 2 == 0; break;
          }
        }
      }
      // occasionally set a single random bit to exercise corner lookups
      if (mode == 1 && (w * h) > 0 && r.nextBoolean()) {
        on[r.nextInt(h)][r.nextInt(w)] = true;
      }
      Object om = oldA.make(w, h, on);
      Object nm = newA.make(w, h, on);
      String[] oldR = { sig(oldA.encl.invoke(om)), sig(oldA.topLeft.invoke(om)), sig(oldA.bottomRight.invoke(om)) };
      String[] newR = { sig(newA.encl.invoke(nm)), sig(newA.topLeft.invoke(nm)), sig(newA.bottomRight.invoke(nm)) };
      total += 3;
      for (int i = 0; i < 3; i++) {
        if (!oldR[i].startsWith("null")) {
          nonNull++;
        }
        if (!oldR[i].equals(newR[i])) {
          mism++;
          if (mism <= 20) {
            System.out.println("DIFF w=" + w + " h=" + h + " method=" + i +
                " old=" + oldR[i] + " new=" + newR[i]);
          }
        }
      }
    }
    System.out.println("Public-method comparisons: " + total + ", non-null results: " + nonNull + ", mismatches: " + mism);
  }
}

